import re

ENT = re.compile(r"^make(?:\[(?P<level>\d+)\])?: (?P<action>Entering|Leaving) directory [`'](?P<dir>.*)'\s*$")
UPD = re.compile(r"^(?P<file>[^:\s]+):(?P<lineno>\d+): update target '(?P<target>[^']*)' due to: (?P<pre>.*\S)\s*$")
MK = re.compile(r"^make(?:\[\d+\])?:")

def parse(lines):
    stack = []
    target = ''
    dirs, dl, upd, ul, cmd, cl = [], [], [], [], [], []
    for i, raw in enumerate(lines):
        s = raw.rstrip()
        if not s.strip():
            continue
        m = ENT.match(s)
        if m:
            lvl = m.group('level') or '0'
            d = m.group('dir')
            act = m.group('action')
            if act == 'Entering':
                stack.append((lvl, d, target))
                target = ''
            else:
                idx = -1
                for j in range(len(stack) - 1, -1, -1):
                    if stack[j][0] == lvl and stack[j][1] == d:
                        idx = j
                        break
                if idx < 0:
                    for j in range(len(stack) - 1, -1, -1):
                        if stack[j][0] == lvl:
                            idx = j
                            break
                if idx >= 0:
                    target = stack[idx][2]
                    del stack[idx:]
            dirs.append({'level': lvl, 'action': act, 'directory': d})
            dl.append(i)
            continue
        cur_dir = stack[-1][1] if stack else ''
        cur_lvl = stack[-1][0] if stack else ''
        m = UPD.match(s)
        if m:
            target = m.group('target')
            upd.append({'directory': cur_dir, 'level': cur_lvl, 'file': m.group('file'), 'line': m.group('lineno'), 'target': target, 'due to': m.group('pre')})
            ul.append(i)
            continue
        if MK.match(s.strip()):
            continue
        cmd.append({'directory': cur_dir, 'level': cur_lvl, 'target': target, 'command': s.strip()})
        cl.append(i)
    blocks = []
    if dirs:
        blocks.append({'name': 'directories', 'kind': 'table', 'lines': dl, 'records': dirs})
    if upd:
        blocks.append({'name': 'updates', 'kind': 'table', 'lines': ul, 'records': upd})
    if cmd:
        blocks.append({'name': 'commands', 'kind': 'table', 'lines': cl, 'records': cmd})
    return {'blocks': blocks, 'skip': []}
